// Simple endless runner based on IDEA.md
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  canvas.width = 800;
  canvas.height = 200;

  const player = { x: 50, y: 150, size: 20, vy: 0, onGround: true };
  const gravity = 0.8;
  const jumpStrength = -12;
  const obstacles = [];
  const obstacleFreq = 1500; // ms
  let lastObstacle = 0;
  let distance = 0;
  let gameOver = false;

  function spawnObstacle() {
    const height = 20 + Math.random() * 30;
    obstacles.push({ x: canvas.width, y: canvas.height - height, w: 20, h: height });
  }

  function reset() {
    player.y = 150;
    player.vy = 0;
    player.onGround = true;
    obstacles.length = 0;
    distance = 0;
    lastObstacle = 0;
    gameOver = false;
  }

  function update(dt) {
    if (gameOver) return;
    // player physics
    player.vy += gravity;
    player.y += player.vy;
    if (player.y + player.size >= canvas.height) {
      player.y = canvas.height - player.size;
      player.vy = 0;
      player.onGround = true;
    } else {
      player.onGround = false;
    }
    // obstacles move left
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= dt * 0.3; // speed
      // collision
      if (
        player.x < o.x + o.w &&
        player.x + player.size > o.x &&
        player.y < o.y + o.h &&
        player.y + player.size > o.y
      ) {
        gameOver = true;
      }
      // remove off-screen
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
    // spawn new obstacles
    if (performance.now() - lastObstacle > obstacleFreq) {
      spawnObstacle();
      lastObstacle = performance.now();
    }
    distance += dt * 0.3;
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // ground
    ctx.fillStyle = '#444';
    ctx.fillRect(0, canvas.height - 10, canvas.width, 10);
    // player
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x, player.y, player.size, player.size);
    // obstacles
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${Math.floor(distance)}`, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2 - 60, canvas.height / 2);
    }
  }

  let lastTime = performance.now();
  function loop() {
    const now = performance.now();
    const dt = now - lastTime;
    lastTime = now;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  // input
  function jump() {
    if (player.onGround && !gameOver) {
      player.vy = jumpStrength;
      player.onGround = false;
    } else if (gameOver) {
      reset();
    }
  }
  window.addEventListener('keydown', e => { if (e.code === 'Space') jump(); });
  canvas.addEventListener('pointerdown', jump);

  reset();
  loop();
})();
